async function loadTrackableCourse(db2, courseId, user) {
  const [course] = await db2.select().from(courses).where(and(eq(courses.id, courseId), isNull(courses.deletedAt))).limit(1);
  if (!course) throw notFound("No se encontr\xF3 el curso.");
  if (user.role === "admin" || user.role === "superadmin") return course;
  if (user.role === "lxd" && course.creatorId === user.id) return course;
  if (user.role === "mentor") {
    const [ok] = await db2.execute(sql`
      select 1 as ok from laboratory_mentors lm
       where lm.user_id = ${user.id}
         and lm.laboratory_id = ${course.laboratoryId}
       limit 1
    `);
    if (ok) return course;
  }
  if (user.role === "advisor" && user.university) {
    const [ok] = await db2.execute(sql`
      select 1 as ok
        from student_course_access a
        join users u on u.id = a.student_id
       where a.course_id = ${course.id}
         and u.university = ${user.university}
       limit 1
    `);
    if (ok) return course;
  }
  throw notFound("No se encontr\xF3 el curso.");
}
